[
  {
    "statement": "No studies have evaluated the effects of limiting dredge width or number of dredges per vessel on marine fish populations.",
    "citations": [
      "3806"
    ]
  },
  {
    "statement": "Related research shows that ceasing mussel dredging entirely in an area closed to all towed fishing gears had no effect on the abundance of bottom-dwelling fish after 10 years.",
    "citations": [
      "2668"
    ]
  },
  {
    "statement": "Ceasing mussel dredging entirely in an area closed to all towed fishing gears resulted in no change in species richness of bottom-dwelling fish compared to before the closure and to open areas.",
    "citations": [
      "2668"
    ]
  },
  {
    "statement": "Sites inside a protected area that had been prohibiting dredging for approximately 2.5 years had different combined invertebrate and fish community composition compared to unprotected dredged sites.",
    "citations": [
      "2228"
    ]
  }
]

[
  {
    "statement": "There is limited research comparing maximum versus minimum landing sizes for commercial fish species.",
    "citations": []
  },
  {
    "statement": "A global review found that only one of five swordfish fisheries showed an increase in recruitment after setting recommended minimum landing sizes and catch limits.",
    "citations": [
      "2735"
    ]
  },
  {
    "statement": "In the same global review, recruitment in other swordfish fisheries was either highly variable or unable to be assessed.",
    "citations": [
      "2735"
    ]
  },
  {
    "statement": "One replicated study in the Ionian Sea found that despite established minimum sizes, most fish landed in commercial catches were immature and had never spawned.",
    "citations": [
      "2735"
    ]
  },
  {
    "statement": "Minimum landing sizes may have limited effectiveness in improving reproductive success.",
    "citations": [
      "2735"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of setting a maximum landing size for commercially fished species on marine fish populations.",
    "citations": [
      "2736"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of specifying a size range of capture for commercially fished species.",
    "citations": [
      "2737"
    ]
  },
  {
    "statement": "The lack of research on maximum landing size limits means there is no evidence available to compare the effectiveness of maximum landing size limits to minimum landing size limits in terms of reproductive success.",
    "citations": []
  }
]

[
  {
    "statement": "Action documents provide very limited evidence specifically addressing the social and economic impacts on fishing communities from establishing long-term fishery closures.",
    "citations": []
  },
  {
    "statement": "The available evidence on fishery closures focuses primarily on biological and ecological effects rather than socioeconomic impacts.",
    "citations": []
  },
  {
    "statement": "The effects of establishing long-term fishery closures were examined across five studies in various marine areas including the Norwegian Sea, North Sea, Gulf of Maine, Bismark Sea, and Kattegat.",
    "citations": [
      "2655"
    ]
  },
  {
    "statement": "No studies were found that examined community responses to long-term fishery closures.",
    "citations": [
      "2655"
    ]
  },
  {
    "statement": "No evidence was found regarding social or economic impacts on fishing communities from long-term fishery closures.",
    "citations": [
      "2655"
    ]
  },
  {
    "statement": "In the Bismark Sea, areas were closed to customary fishing, which is indigenous fishing for cultural and community needs.",
    "citations": [
      "2675"
    ]
  },
  {
    "statement": "A closure of customary fishing areas for eight years in the Bismark Sea affected fish abundance and behavior.",
    "citations": [
      "2675"
    ]
  },
  {
    "statement": "A document regarding the Bismark Sea closure does not address the social or economic impacts on the indigenous fishing communities affected by the prohibition.",
    "citations": [
      "2675"
    ]
  },
  {
    "statement": "Several management approaches that could relate to community impacts were identified, including community-based fisheries management, territorial user rights for fisheries, and allowing only small-scale traditional fishing.",
    "citations": [
      "2242",
      "2104",
      "2678"
    ]
  },
  {
    "statement": "The identified management approaches do not provide evidence about the socioeconomic effects of fishery closures on communities.",
    "citations": [
      "2242",
      "2104",
      "2678"
    ]
  },
  {
    "statement": "No studies were found that evaluated stakeholder engagement when designing Marine Protected Areas.",
    "citations": [
      "2243"
    ]
  },
  {
    "statement": "No studies were found that evaluated the practice of purchasing fishing vessels from fishers.",
    "citations": [
      "3819"
    ]
  },
  {
    "statement": "No studies were found that evaluated introducing economic incentives for sustainable fishing.",
    "citations": [
      "2811"
    ]
  },
  {
    "statement": "No studies were found that evaluated including fishers in management groups.",
    "citations": [
      "2809"
    ]
  },
  {
    "statement": "A significant research gap exists in understanding the community impacts of fishery management measures.",
    "citations": [
      "2243",
      "3819",
      "2811",
      "2809"
    ]
  }
]
